dictionary["Histograma de luminosidade da imagem"]={"en": "Image luminance histogram", "es": "Histograma de luminosidad", "ja": "輝度ヒストグラム", "zh": "图像亮度直方图", "de": "Helligkeitshistogramm", "fr": "Histogramme de luminosité", "it": "Istogramma della luminosità"};reverse.set(normalize("Histograma de luminosidade da imagem"),"Histograma de luminosidade da imagem");
dictionary["Sombras \u00e0 esquerda, realces \u00e0 direita. Os ajustes preservam os pixels de origem."]={"en": "Shadows on the left, highlights on the right. Adjustments preserve the source pixels.", "es": "Sombras a la izquierda, luces a la derecha. Los ajustes conservan los píxeles originales.", "ja": "左がシャドウ、右がハイライトです。元の画素は保持されます。", "zh": "左侧为阴影，右侧为高光。调整保留原始像素。", "de": "Schatten links, Lichter rechts. Die Originalpixel bleiben erhalten.", "fr": "Ombres à gauche, hautes lumières à droite. Les pixels sources sont préservés.", "it": "Ombre a sinistra, luci a destra. Le regolazioni preservano i pixel originali."};reverse.set(normalize("Sombras \u00e0 esquerda, realces \u00e0 direita. Os ajustes preservam os pixels de origem."),"Sombras \u00e0 esquerda, realces \u00e0 direita. Os ajustes preservam os pixels de origem.");
dictionary["Selecione textos, formas ou imagens sobrepostas para editar. A imagem base permanece no fundo."]={"en": "Select text, shapes or image layers to edit. The base image stays in the background.", "es": "Selecciona texto, formas o capas de imagen para editar. La imagen base permanece al fondo.", "ja": "文字、図形、画像レイヤーを選択して編集します。元画像は背景に残ります。", "zh": "选择文字、形状或图像图层进行编辑。底图保持在背景。", "de": "Wähle Texte, Formen oder Bildebenen zur Bearbeitung. Das Basisbild bleibt im Hintergrund.", "fr": "Sélectionnez du texte, des formes ou des calques d’image. L’image de base reste au fond.", "it": "Seleziona testi, forme o livelli immagine da modificare. L’immagine base rimane sullo sfondo."};reverse.set(normalize("Selecione textos, formas ou imagens sobrepostas para editar. A imagem base permanece no fundo."),"Selecione textos, formas ou imagens sobrepostas para editar. A imagem base permanece no fundo.");
dictionary["Ctrl + Z desfaz. Os filtros e ajustes continuam edit\u00e1veis at\u00e9 aplicar uma edi\u00e7\u00e3o raster."]={"en": "Ctrl + Z undoes. Filters and adjustments remain editable until a raster edit is applied.", "es": "Ctrl + Z deshace. Los filtros y ajustes siguen editables hasta aplicar una edición ráster.", "ja": "Ctrl + Zで元に戻します。ラスタ編集を適用するまでフィルターと調整は変更できます。", "zh": "Ctrl + Z撤销。在应用栅格编辑前，滤镜和调整仍可修改。", "de": "Ctrl + Z macht rückgängig. Filter und Anpassungen bleiben bis zur Rasterbearbeitung editierbar.", "fr": "Ctrl + Z annule. Les filtres et réglages restent modifiables jusqu’à une retouche raster.", "it": "Ctrl + Z annulla. Filtri e regolazioni restano modificabili fino a una modifica raster."};reverse.set(normalize("Ctrl + Z desfaz. Os filtros e ajustes continuam edit\u00e1veis at\u00e9 aplicar uma edi\u00e7\u00e3o raster."),"Ctrl + Z desfaz. Os filtros e ajustes continuam edit\u00e1veis at\u00e9 aplicar uma edi\u00e7\u00e3o raster.");
dictionary["Salvar projeto agora"]={"en": "Save project now", "es": "Guardar proyecto ahora", "ja": "今すぐ保存", "zh": "立即保存项目", "de": "Projekt jetzt speichern", "fr": "Enregistrer le projet", "it": "Salva progetto ora"};reverse.set(normalize("Salvar projeto agora"),"Salvar projeto agora");
dictionary["O projeto ser\u00e1 salvo automaticamente neste navegador."]={"en": "The project will be saved automatically in this browser.", "es": "El proyecto se guardará automáticamente en este navegador.", "ja": "プロジェクトはこのブラウザに自動保存されます。", "zh": "项目将自动保存在此浏览器中。", "de": "Das Projekt wird automatisch in diesem Browser gespeichert.", "fr": "Le projet sera enregistré automatiquement dans ce navigateur.", "it": "Il progetto verrà salvato automaticamente in questo browser."};reverse.set(normalize("O projeto ser\u00e1 salvo automaticamente neste navegador."),"O projeto ser\u00e1 salvo automaticamente neste navegador.");
dictionary["Altera\u00e7\u00f5es ainda n\u00e3o salvas neste navegador."]={"en": "Changes have not been saved in this browser yet.", "es": "Los cambios aún no se han guardado en este navegador.", "ja": "変更はまだ保存されていません。", "zh": "更改尚未保存在此浏览器中。", "de": "Änderungen sind noch nicht im Browser gespeichert.", "fr": "Les modifications ne sont pas encore enregistrées.", "it": "Le modifiche non sono ancora salvate nel browser."};reverse.set(normalize("Altera\u00e7\u00f5es ainda n\u00e3o salvas neste navegador."),"Altera\u00e7\u00f5es ainda n\u00e3o salvas neste navegador.");
dictionary["Salvando projeto neste navegador\u2026"]={"en": "Saving project in this browser…", "es": "Guardando proyecto en este navegador…", "ja": "ブラウザに保存中…", "zh": "正在保存项目…", "de": "Projekt wird im Browser gespeichert…", "fr": "Enregistrement du projet…", "it": "Salvataggio del progetto…"};reverse.set(normalize("Salvando projeto neste navegador\u2026"),"Salvando projeto neste navegador\u2026");
dictionary["Projeto salvo neste navegador."]={"en": "Project saved in this browser.", "es": "Proyecto guardado en este navegador.", "ja": "プロジェクトを保存しました。", "zh": "项目已保存在此浏览器中。", "de": "Projekt im Browser gespeichert.", "fr": "Projet enregistré dans ce navigateur.", "it": "Progetto salvato in questo browser."};reverse.set(normalize("Projeto salvo neste navegador."),"Projeto salvo neste navegador.");
dictionary["Projeto recuperado neste navegador."]={"en": "Project restored in this browser.", "es": "Proyecto recuperado en este navegador.", "ja": "プロジェクトを復元しました。", "zh": "已恢复项目。", "de": "Projekt im Browser wiederhergestellt.", "fr": "Projet restauré dans ce navigateur.", "it": "Progetto ripristinato in questo browser."};reverse.set(normalize("Projeto recuperado neste navegador."),"Projeto recuperado neste navegador.");
dictionary["N\u00e3o foi poss\u00edvel salvar automaticamente. Mantenha esta aba aberta e exporte sua imagem."]={"en": "Automatic saving failed. Keep this tab open and export your image.", "es": "No se pudo guardar automáticamente. Mantén esta pestaña abierta y exporta la imagen.", "ja": "自動保存に失敗しました。タブを開いたまま画像を書き出してください。", "zh": "自动保存失败。请保持标签页打开并导出图像。", "de": "Automatisches Speichern fehlgeschlagen. Lass den Tab offen und exportiere das Bild.", "fr": "Échec de l’enregistrement automatique. Gardez cet onglet ouvert et exportez l’image.", "it": "Salvataggio automatico fallito. Mantieni la scheda aperta ed esporta l’immagine."};reverse.set(normalize("N\u00e3o foi poss\u00edvel salvar automaticamente. Mantenha esta aba aberta e exporte sua imagem."),"N\u00e3o foi poss\u00edvel salvar automaticamente. Mantenha esta aba aberta e exporte sua imagem.");
dictionary["N\u00e3o foi poss\u00edvel recuperar o projeto. O salvamento local pode estar indispon\u00edvel."]={"en": "The project could not be restored. Local storage may be unavailable.", "es": "No se pudo recuperar el proyecto. El almacenamiento local puede no estar disponible.", "ja": "復元できませんでした。ローカル保存が利用できない可能性があります。", "zh": "无法恢复项目。本地存储可能不可用。", "de": "Das Projekt konnte nicht wiederhergestellt werden. Lokaler Speicher ist eventuell nicht verfügbar.", "fr": "Impossible de restaurer le projet. Le stockage local est peut-être indisponible.", "it": "Impossibile ripristinare il progetto. La memoria locale potrebbe non essere disponibile."};reverse.set(normalize("N\u00e3o foi poss\u00edvel recuperar o projeto. O salvamento local pode estar indispon\u00edvel."),"N\u00e3o foi poss\u00edvel recuperar o projeto. O salvamento local pode estar indispon\u00edvel.");
dictionary["Arquivo preparado:"]={"en": "File ready:", "es": "Archivo preparado:", "ja": "ファイル準備完了：", "zh": "文件已准备：", "de": "Datei bereit:", "fr": "Fichier prêt :", "it": "File pronto:"};reverse.set(normalize("Arquivo preparado:"),"Arquivo preparado:");
dictionary["PDF criado com {n} p\u00e1gina(s)."]={"en": "PDF created with {n} page(s).", "es": "PDF creado con {n} página(s).", "ja": "{n}ページのPDFを作成しました。", "zh": "已创建包含{n}页的PDF。", "de": "PDF mit {n} Seite(n) erstellt.", "fr": "PDF créé avec {n} page(s).", "it": "PDF creato con {n} pagina/e."};reverse.set(normalize("PDF criado com {n} p\u00e1gina(s)."),"PDF criado com {n} p\u00e1gina(s).");
dictionary["{n} imagens processadas e reunidas em ZIP."]={"en": "{n} images processed and packed into a ZIP.", "es": "{n} imágenes procesadas y reunidas en ZIP.", "ja": "{n}枚の画像を処理しZIPにまとめました。", "zh": "已处理{n}张图像并打包为ZIP。", "de": "{n} Bilder verarbeitet und als ZIP gepackt.", "fr": "{n} images traitées et regroupées en ZIP.", "it": "{n} immagini elaborate e raccolte in ZIP."};reverse.set(normalize("{n} imagens processadas e reunidas em ZIP."),"{n} imagens processadas e reunidas em ZIP.");
dictionary["Recorte aplicado. Desfazer recupera o enquadramento anterior."]={"en": "Crop applied. Undo restores the previous framing.", "es": "Recorte aplicado. Deshacer recupera el encuadre anterior.", "ja": "トリミングしました。「元に戻す」で以前の構図に戻れます。", "zh": "已应用裁剪。撤销可恢复之前的构图。", "de": "Zuschnitt angewendet. Rückgängig stellt den vorherigen Ausschnitt wieder her.", "fr": "Recadrage appliqué. Annuler restaure le cadrage précédent.", "it": "Ritaglio applicato. Annulla ripristina l’inquadratura precedente."};reverse.set(normalize("Recorte aplicado. Desfazer recupera o enquadramento anterior."),"Recorte aplicado. Desfazer recupera o enquadramento anterior.");
dictionary["Imagem editada"]={"en": "Edited image", "es": "Imagen editada", "ja": "編集済み画像", "zh": "已编辑图像", "de": "Bearbeitetes Bild", "fr": "Image retouchée", "it": "Immagine modificata"};reverse.set(normalize("Imagem editada"),"Imagem editada");
dictionary["Arquivo de imagem inv\u00e1lido."]={"en": "Invalid image file.", "es": "Archivo de imagen inválido.", "ja": "無効な画像ファイルです。", "zh": "无效的图像文件。", "de": "Ungültige Bilddatei.", "fr": "Fichier image invalide.", "it": "File immagine non valido."};reverse.set(normalize("Arquivo de imagem inv\u00e1lido."),"Arquivo de imagem inv\u00e1lido.");

// Photo Story 22: task-focused home and clear local processing notice.
dictionary["Como voc\u00ea quer transformar sua imagem?"]={"en": "How would you like to transform your image?", "es": "¿Cómo quieres transformar tu imagen?", "ja": "画像をどう編集しますか？", "zh": "您想如何编辑图像？", "de": "Wie möchtest du dein Bild verändern?", "fr": "Comment souhaitez-vous transformer votre image ?", "it": "Come vuoi trasformare la tua immagine?"};reverse.set(normalize("Como voc\u00ea quer transformar sua imagem?"),"Como voc\u00ea quer transformar sua imagem?");
dictionary["Respostas r\u00e1pidas para usar as ferramentas."]={"en": "Quick answers to help you use the tools.", "es": "Respuestas rápidas para usar las herramientas.", "ja": "ツールの使い方をすぐ確認できます。", "zh": "快速了解工具的用法。", "de": "Schnelle Antworten zu den Werkzeugen.", "fr": "Des réponses rapides pour utiliser les outils.", "it": "Risposte rapide per usare gli strumenti."};reverse.set(normalize("Respostas r\u00e1pidas para usar as ferramentas."),"Respostas r\u00e1pidas para usar as ferramentas.");
dictionary["Como remover o fundo e manter a transpar\u00eancia?"]={"en": "How do I remove the background and keep transparency?", "es": "¿Cómo quitar el fondo y conservar la transparencia?", "ja": "背景を削除して透明にするには？", "zh": "如何移除背景并保留透明度？", "de": "Wie entferne ich den Hintergrund und behalte Transparenz?", "fr": "Comment supprimer le fond et garder la transparence ?", "it": "Come rimuovere lo sfondo e mantenere la trasparenza?"};reverse.set(normalize("Como remover o fundo e manter a transpar\u00eancia?"),"Como remover o fundo e manter a transpar\u00eancia?");
dictionary["Abra Remover fundo, aplique a IA e exporte em PNG ou WebP. JPG n\u00e3o preserva transpar\u00eancia."]={"en": "Open Remove background, apply AI and export as PNG or WebP. JPG does not preserve transparency.", "es": "Abre Quitar fondo, aplica la IA y exporta PNG o WebP. JPG no conserva transparencia.", "ja": "「背景を削除」でAIを適用し、PNGかWebPで書き出します。JPGは透明度を保持しません。", "zh": "打开移除背景，应用AI并导出PNG或WebP。JPG不保留透明度。", "de": "Öffne Hintergrund entfernen, wende KI an und exportiere PNG oder WebP. JPG erhält keine Transparenz.", "fr": "Ouvrez Supprimer le fond, appliquez l’IA puis exportez en PNG ou WebP. JPG ne garde pas la transparence.", "it": "Apri Rimuovi sfondo, applica l’IA ed esporta in PNG o WebP. JPG non mantiene la trasparenza."};reverse.set(normalize("Abra Remover fundo, aplique a IA e exporte em PNG ou WebP. JPG n\u00e3o preserva transpar\u00eancia."),"Abra Remover fundo, aplique a IA e exporte em PNG ou WebP. JPG n\u00e3o preserva transpar\u00eancia.");
dictionary["Como ampliar uma imagem em 2\u00d7 ou 4\u00d7?"]={"en": "How do I upscale an image by 2× or 4×?", "es": "¿Cómo ampliar una imagen 2× o 4×?", "ja": "画像を2倍または4倍に拡大するには？", "zh": "如何将图像放大2倍或4倍？", "de": "Wie vergrößere ich ein Bild auf 2× oder 4×?", "fr": "Comment agrandir une image en 2× ou 4× ?", "it": "Come ingrandire un’immagine di 2× o 4×?"};reverse.set(normalize("Como ampliar uma imagem em 2\u00d7 ou 4\u00d7?"),"Como ampliar uma imagem em 2\u00d7 ou 4\u00d7?");
dictionary["Em Aumentar resolu\u00e7\u00e3o, escolha 2\u00d7 ou 4\u00d7 e aplique a IA. O tamanho n\u00e3o \u00e9 reduzido automaticamente; imagens grandes exigem mais tempo e mem\u00f3ria."]={"en": "In Increase resolution, choose 2× or 4× and apply AI. The target size is not reduced automatically; large images need more time and memory.", "es": "En Aumentar resolución, elige 2× o 4× y aplica la IA. El tamaño no se reduce automáticamente; las imágenes grandes requieren más tiempo y memoria.", "ja": "「解像度を上げる」で2倍か4倍を選びAIを適用します。サイズは自動縮小されません。大きな画像には時間とメモリが必要です。", "zh": "在提高分辨率中选择2倍或4倍并应用AI。不会自动缩小目标尺寸；大图需要更多时间和内存。", "de": "Wähle unter Auflösung erhöhen 2× oder 4× und wende KI an. Die Zielgröße wird nicht automatisch reduziert; große Bilder brauchen mehr Zeit und Speicher.", "fr": "Dans Augmenter la résolution, choisissez 2× ou 4× et appliquez l’IA. La taille n’est pas réduite automatiquement ; les grandes images demandent plus de temps et de mémoire.", "it": "In Aumenta risoluzione, scegli 2× o 4× e applica l’IA. La dimensione non viene ridotta automaticamente; le immagini grandi richiedono più tempo e memoria."};reverse.set(normalize("Em Aumentar resolu\u00e7\u00e3o, escolha 2\u00d7 ou 4\u00d7 e aplique a IA. O tamanho n\u00e3o \u00e9 reduzido automaticamente; imagens grandes exigem mais tempo e mem\u00f3ria."),"Em Aumentar resolu\u00e7\u00e3o, escolha 2\u00d7 ou 4\u00d7 e aplique a IA. O tamanho n\u00e3o \u00e9 reduzido automaticamente; imagens grandes exigem mais tempo e mem\u00f3ria.");
dictionary["Como criar um story com textos e camadas?"]={"en": "How do I create a story with text and layers?", "es": "¿Cómo crear una story con textos y capas?", "ja": "文字やレイヤーを使ってストーリーを作るには？", "zh": "如何使用文字和图层创建故事？", "de": "Wie erstelle ich eine Story mit Text und Ebenen?", "fr": "Comment créer une story avec du texte et des calques ?", "it": "Come creare una storia con testi e livelli?"};reverse.set(normalize("Como criar um story com textos e camadas?"),"Como criar um story com textos e camadas?");
dictionary["Abra Criar stories. Adicione textos e elementos. No modo Avan\u00e7ado, ajuste a ordem, a opacidade e a visibilidade das camadas."]={"en": "Open Create stories. Add text and elements. In Advanced mode, adjust layer order, opacity and visibility.", "es": "Abre Crear stories. Añade textos y elementos. En modo Avanzado, ajusta el orden, la opacidad y la visibilidad de las capas.", "ja": "「ストーリーを作成」で文字や素材を追加します。詳細モードではレイヤーの順序、不透明度、表示を調整できます。", "zh": "打开创建故事，添加文字和元素。在高级模式中调整图层顺序、不透明度和可见性。", "de": "Öffne Storys erstellen und füge Texte und Elemente hinzu. Im erweiterten Modus passt du Ebenenreihenfolge, Deckkraft und Sichtbarkeit an.", "fr": "Ouvrez Créer des stories et ajoutez texte et éléments. Le mode Avancé permet de régler l’ordre, l’opacité et la visibilité des calques.", "it": "Apri Crea storie e aggiungi testi ed elementi. In modalità Avanzata, regola ordine, opacità e visibilità dei livelli."};reverse.set(normalize("Abra Criar stories. Adicione textos e elementos. No modo Avan\u00e7ado, ajuste a ordem, a opacidade e a visibilidade das camadas."),"Abra Criar stories. Adicione textos e elementos. No modo Avan\u00e7ado, ajuste a ordem, a opacidade e a visibilidade das camadas.");
dictionary["Como converter ou comprimir v\u00e1rias imagens?"]={"en": "How do I convert or compress several images?", "es": "¿Cómo convertir o comprimir varias imágenes?", "ja": "複数の画像を変換・圧縮するには？", "zh": "如何转换或压缩多张图像？", "de": "Wie konvertiere oder komprimiere ich mehrere Bilder?", "fr": "Comment convertir ou compresser plusieurs images ?", "it": "Come convertire o comprimere più immagini?"};reverse.set(normalize("Como converter ou comprimir v\u00e1rias imagens?"),"Como converter ou comprimir v\u00e1rias imagens?");
dictionary["Use Em lote para escolher o formato, a qualidade e o lado m\u00e1ximo. O ZIP usa as imagens de origem da galeria, sem o recorte e as camadas da composi\u00e7\u00e3o."]={"en": "Use Batch to choose format, quality and maximum side. The ZIP uses gallery source images, without the composition’s crop and layers.", "es": "Usa En lote para elegir formato, calidad y lado máximo. El ZIP usa las imágenes originales de la galería, sin el recorte ni las capas de la composición.", "ja": "一括処理で形式、品質、最大辺を選びます。ZIPにはギャラリーの元画像が使われ、構図の切り抜きやレイヤーは含まれません。", "zh": "使用批量处理选择格式、质量和最长边。ZIP使用图库原图，不包含当前作品的裁剪和图层。", "de": "Wähle in Stapelverarbeitung Format, Qualität und maximale Kantenlänge. Das ZIP verwendet die Quellbilder der Galerie ohne Zuschnitt und Ebenen der Komposition.", "fr": "Dans Traitement par lot, choisissez format, qualité et côté maximal. Le ZIP utilise les images sources de la galerie, sans le recadrage ni les calques de la composition.", "it": "Usa In blocco per scegliere formato, qualità e lato massimo. Lo ZIP usa le immagini originali della galleria, senza ritaglio e livelli della composizione."};reverse.set(normalize("Use Em lote para escolher o formato, a qualidade e o lado m\u00e1ximo. O ZIP usa as imagens de origem da galeria, sem o recorte e as camadas da composi\u00e7\u00e3o."),"Use Em lote para escolher o formato, a qualidade e o lado m\u00e1ximo. O ZIP usa as imagens de origem da galeria, sem o recorte e as camadas da composi\u00e7\u00e3o.");
dictionary["Como extrair o texto de uma imagem?"]={"en": "How do I extract text from an image?", "es": "¿Cómo extraer el texto de una imagen?", "ja": "画像から文字を抽出するには？", "zh": "如何从图像中提取文字？", "de": "Wie extrahiere ich Text aus einem Bild?", "fr": "Comment extraire le texte d’une image ?", "it": "Come estrarre il testo da un’immagine?"};reverse.set(normalize("Como extrair o texto de uma imagem?"),"Como extrair o texto de uma imagem?");
dictionary["Abra Extrair texto, escolha o idioma e reconhe\u00e7a. Confira o resultado antes de copiar ou baixar o TXT; letras decorativas e imagens pouco n\u00edtidas podem causar erros."]={"en": "Open Extract text, choose the language and recognize. Review the result before copying or downloading TXT; decorative letters and blurry images can cause errors.", "es": "Abre Extraer texto, elige el idioma y reconoce. Revisa antes de copiar o descargar TXT; las letras decorativas y las imágenes borrosas pueden causar errores.", "ja": "「文字を抽出」で言語を選んで認識します。コピーやTXT保存の前に確認してください。装飾文字やぼけた画像では誤認識することがあります。", "zh": "打开提取文字，选择语言并识别。复制或下载TXT前请检查；装饰字体和模糊图像可能导致错误。", "de": "Öffne Text extrahieren, wähle die Sprache und starte die Erkennung. Prüfe das Ergebnis vor dem Kopieren oder TXT-Download; Schmuckschriften und unscharfe Bilder können Fehler verursachen.", "fr": "Ouvrez Extraire le texte, choisissez la langue et lancez la reconnaissance. Relisez avant de copier ou télécharger le TXT ; les lettres décoratives et images floues peuvent entraîner des erreurs.", "it": "Apri Estrai testo, scegli la lingua e avvia il riconoscimento. Controlla prima di copiare o scaricare il TXT; caratteri decorativi e immagini sfocate possono causare errori."};reverse.set(normalize("Abra Extrair texto, escolha o idioma e reconhe\u00e7a. Confira o resultado antes de copiar ou baixar o TXT; letras decorativas e imagens pouco n\u00edtidas podem causar erros."),"Abra Extrair texto, escolha o idioma e reconhe\u00e7a. Confira o resultado antes de copiar ou baixar o TXT; letras decorativas e imagens pouco n\u00edtidas podem causar erros.");
dictionary["Como continuar a edi\u00e7\u00e3o ap\u00f3s atualizar a p\u00e1gina?"]={"en": "How do I continue editing after refreshing the page?", "es": "¿Cómo continuar la edición después de actualizar la página?", "ja": "ページを更新した後に編集を続けるには？", "zh": "刷新页面后如何继续编辑？", "de": "Wie bearbeite ich nach dem Neuladen weiter?", "fr": "Comment reprendre après avoir actualisé la page ?", "it": "Come continuare dopo aver aggiornato la pagina?"};reverse.set(normalize("Como continuar a edi\u00e7\u00e3o ap\u00f3s atualizar a p\u00e1gina?"),"Como continuar a edi\u00e7\u00e3o ap\u00f3s atualizar a p\u00e1gina?");
dictionary["Aguarde a indica\u00e7\u00e3o de projeto salvo. Na mesma aba, o navegador recupera imagens, ajustes e camadas. O hist\u00f3rico de desfazer n\u00e3o \u00e9 recuperado. Limpar os dados do site pode apagar o projeto."]={"en": "Wait for the saved-project message. In the same tab, the browser restores images, adjustments and layers. Undo history is not restored. Clearing site data can erase the project.", "es": "Espera el aviso de proyecto guardado. En la misma pestaña se recuperan imágenes, ajustes y capas. No se recupera el historial de deshacer. Borrar los datos del sitio puede eliminar el proyecto.", "ja": "保存完了の表示を待ってください。同じタブでは画像、調整、レイヤーが復元されます。元に戻す履歴は復元されません。サイトデータの削除でプロジェクトが消える場合があります。", "zh": "请等待项目已保存提示。同一标签页中可恢复图像、调整和图层，但不会恢复撤销历史。清除站点数据可能会删除项目。", "de": "Warte auf die Speichermeldung. Im selben Tab werden Bilder, Anpassungen und Ebenen wiederhergestellt, aber kein Rückgängig-Verlauf. Das Löschen der Websitedaten kann das Projekt entfernen.", "fr": "Attendez le message d’enregistrement. Dans le même onglet, le navigateur restaure images, réglages et calques, mais pas l’historique d’annulation. Effacer les données du site peut supprimer le projet.", "it": "Attendi il messaggio di salvataggio. Nella stessa scheda vengono ripristinati immagini, regolazioni e livelli, ma non la cronologia di annullamento. Cancellare i dati del sito può eliminare il progetto."};reverse.set(normalize("Aguarde a indica\u00e7\u00e3o de projeto salvo. Na mesma aba, o navegador recupera imagens, ajustes e camadas. O hist\u00f3rico de desfazer n\u00e3o \u00e9 recuperado. Limpar os dados do site pode apagar o projeto."),"Aguarde a indica\u00e7\u00e3o de projeto salvo. Na mesma aba, o navegador recupera imagens, ajustes e camadas. O hist\u00f3rico de desfazer n\u00e3o \u00e9 recuperado. Limpar os dados do site pode apagar o projeto.");
dictionary["Suas imagens, sob seu controle."]={"en": "Your images, under your control.", "es": "Tus imágenes, bajo tu control.", "ja": "画像はあなたが管理。", "zh": "您的图像，由您掌控。", "de": "Deine Bilder unter deiner Kontrolle.", "fr": "Vos images, sous votre contrôle.", "it": "Le tue immagini, sotto il tuo controllo."};reverse.set(normalize("Suas imagens, sob seu controle."),"Suas imagens, sob seu controle.");
dictionary["Ao abrir uma imagem, voc\u00ea solicita apenas o processamento local para edi\u00e7\u00e3o. Isso n\u00e3o autoriza o Photo Story a publicar, reutilizar ou acessar sua imagem."]={"en": "Opening an image requests local processing for editing only. It does not authorize Photo Story to publish, reuse or access your image.", "es": "Abrir una imagen solicita solo su procesamiento local para editar. No autoriza a Photo Story a publicar, reutilizar o acceder a ella.", "ja": "画像を開く操作は端末内での編集処理のみを依頼します。Photo Storyによる公開、再利用、画像へのアクセスを許可するものではありません。", "zh": "打开图像仅请求在本地进行编辑处理，并不授权Photo Story发布、重复使用或访问您的图像。", "de": "Das Öffnen eines Bildes fordert nur lokale Bearbeitung an. Es erlaubt Photo Story nicht, dein Bild zu veröffentlichen, wiederzuverwenden oder darauf zuzugreifen.", "fr": "Ouvrir une image demande uniquement son traitement local pour la retouche. Cela n’autorise pas Photo Story à la publier, la réutiliser ou y accéder.", "it": "Aprire un’immagine richiede solo l’elaborazione locale per modificarla. Non autorizza Photo Story a pubblicarla, riutilizzarla o accedervi."};reverse.set(normalize("Ao abrir uma imagem, voc\u00ea solicita apenas o processamento local para edi\u00e7\u00e3o. Isso n\u00e3o autoriza o Photo Story a publicar, reutilizar ou acessar sua imagem."),"Ao abrir uma imagem, voc\u00ea solicita apenas o processamento local para edi\u00e7\u00e3o. Isso n\u00e3o autoriza o Photo Story a publicar, reutilizar ou acessar sua imagem.");
dictionary["Entenda a privacidade das imagens \u2197"]={"en": "Learn about image privacy ↗", "es": "Conoce la privacidad de las imágenes ↗", "ja": "画像のプライバシーについて ↗", "zh": "了解图像隐私 ↗", "de": "Mehr zum Bilddatenschutz ↗", "fr": "Comprendre la confidentialité des images ↗", "it": "Scopri la privacy delle immagini ↗"};reverse.set(normalize("Entenda a privacidade das imagens \u2197"),"Entenda a privacidade das imagens \u2197");
dictionary["Remova fundos e amplie em 2\u00d7 ou 4\u00d7 com modelos locais, sem enviar suas fotos para uma API."]={"en": "Remove backgrounds and upscale by 2× or 4× with local models, without sending photos to an API.", "es": "Quita fondos y amplía 2× o 4× con modelos locales, sin enviar fotos a una API.", "ja": "ローカルモデルで背景削除と2倍・4倍拡大。写真はAPIに送信しません。", "zh": "使用本地模型移除背景并放大2倍或4倍，无需向API发送照片。", "de": "Entferne Hintergründe und vergrößere 2× oder 4× mit lokalen Modellen, ohne Fotos an eine API zu senden.", "fr": "Supprimez les fonds et agrandissez en 2× ou 4× avec des modèles locaux, sans envoyer de photos à une API.", "it": "Rimuovi sfondi e ingrandisci di 2× o 4× con modelli locali, senza inviare foto a un’API."};reverse.set(normalize("Remova fundos e amplie em 2\u00d7 ou 4\u00d7 com modelos locais, sem enviar suas fotos para uma API."),"Remova fundos e amplie em 2\u00d7 ou 4\u00d7 com modelos locais, sem enviar suas fotos para uma API.");
