$('runDiagnostics').onclick=async()=>{if(busy)return;setBusy(true,true);aiCancelled=false;const rows=[],check=async(name,fn)=>{try{const detail=await fn();rows.push({name,status:'ok',detail})}catch(e){rows.push({name,status:'error',detail:String(e.message).slice(0,500)})}$('diagnosticsOutput').hidden=false;$('diagnosticsOutput').textContent=t('DIAG_RUNNING')};setProgress(t('DIAG_RUNNING'));await check('WebAssembly',()=>{if(!globalThis.WebAssembly)throw Error('WORKER_UNSUPPORTED');return 'available'});await check('Local assets',async()=>{for(const path of ['u2netp.onnx','model.json','ort-wasm-simd-threaded.wasm','tfjs-backend-wasm-simd.wasm','worker.min.js']){const r=await fetch(path,{method:'HEAD',cache:'no-store'});if(!r.ok)throw Error(path+': HTTP '+r.status)}return '5 assets available'});if(!aiCancelled)await check('ESRGAN inference',async()=>{const pixels=new Uint8ClampedArray(16*16*4);pixels.fill(128);const r=await upscaleEngine.run({pixels,width:16,height:16},()=>{},120000);normalizeAlpha(r);if(r.width!==32||r.height!==32)throw Error('AI_INVALID_IMAGE');return '16 × 16 → 32 × 32'});if(!aiCancelled)await check('Vision inference',async()=>{const c=state.source?buildImage(320,true,true):makeCanvas(320,320),inputCanvas=makeCanvas(320,320),x=inputCanvas.getContext('2d');x.drawImage(c,0,0,320,320);try{const r=await visionEngine.run({input:segmentationInput(x.getImageData(0,0,320,320).data)},()=>{},120000);if(r.mask?.length!==320*320)throw Error('AI_INVALID_IMAGE');return '320 × 320 mask'}catch(e){if(e.message==='NO_SUBJECT')return 'Model loaded; no clear subject in test image';throw e}});if(!aiCancelled)await check('OCR inference',async()=>{if(!window.Tesseract)await loadScript('tesseract.min.js');const worker=await window.Tesseract.createWorker('eng',1,{workerPath:new URL('./worker.min.js',import.meta.url).href,workerBlobURL:false,corePath:new URL('././',import.meta.url).href,langPath:new URL('././',import.meta.url).href,cacheMethod:'write'});try{const c=makeCanvas(420,90),x=c.getContext('2d');x.fillStyle='#ffffff';x.fillRect(0,0,420,90);x.fillStyle='#000000';x.font='32px Arial';x.fillText('Photo Story 2026',20,57);await worker.setParameters({tessedit_pageseg_mode:'7'});const r=await worker.recognize(c);if(!r.data.text.includes('Photo'))throw Error('OCR_UNCERTAIN');return r.data.text.trim()}finally{await worker.terminate()}});diagnosticsReport={version:9,browser:navigator.userAgent,time:new Date().toISOString(),tests:rows,lastProblem,vision:visionEngine.lastError,upscale:upscaleEngine.lastError};$('diagnosticsOutput').textContent=rows.map(r=>(r.status==='ok'?'✓ ':'× ')+r.name+': '+r.detail).join('\n');$('saveDiagnostics').hidden=false;setBusy(false);message(t('DIAG_DONE'))};$('saveDiagnostics').onclick=()=>{if(diagnosticsReport)downloadBlob(new Blob([JSON.stringify(diagnosticsReport,null,2)],{type:'application/json'}),'photo-story-diagnostico.json')};

