async function reportAIError(error){let text=error.message==='UPSCALE_MEMORY'?({pt:'O navegador não conseguiu reservar memória para este tamanho. A imagem foi preservada. Tente 2× ou use um computador com mais memória.',en:'The browser could not allocate memory for this size. Your image was preserved. Try 2× or a computer with more memory.',es:'El navegador no pudo reservar memoria para este tamaño. Tu imagen se conservó. Prueba 2× o un ordenador con más memoria.',fr:'Mémoire insuffisante pour cette taille. Votre image est conservée. Essayez 2× ou un ordinateur avec plus de mémoire.',de:'Nicht genug Browserspeicher für diese Größe. Das Bild bleibt erhalten. Versuche 2× oder einen Computer mit mehr Speicher.',it:'Memoria insufficiente per queste dimensioni. L’immagine è conservata. Prova 2× o un computer con più memoria.',ja:'このサイズに必要なメモリを確保できませんでした。元画像は保持されています。2×またはメモリの多いパソコンをお試しください。',zh:'浏览器无法为此尺寸分配内存。原图已保留。请尝试2×或使用内存更大的电脑。'}[language()]||'Insufficient browser memory. Your image was preserved.'):t(error.message);if(typeof fetch==='function'&&/^(WORKER_FAILED|MODEL_FAILED|MODEL_HTTP_)/.test(error.message)){const paths=['vision-worker.js','upscale-worker.js','u2netp.onnx','model.json','tf.min.js','ort.wasm.min.js','ort-wasm-simd-threaded.wasm'];const missing=[];await Promise.all(paths.map(async path=>{try{const response=await fetch(path,{method:'HEAD',cache:'no-store',signal:AbortSignal.timeout(8000)});if(!response.ok)missing.push(path)}catch{}}));if(missing.length)text=t('Faltam arquivos da IA na publicação.')+' '+missing.join(', ')+'. '+t('Abra Verificar publicação no rodapé para conferir todos os arquivos.')}message(text,error.message!=='AI_CANCELLED')}

