const EXPORT_FIELDS=['filename','format','quality','target','batchFormat','batchQuality','batchMax','batchAdjust','batchMark','pdfContent','pdfPage','pdfMargin','pdfPages','ocrLanguage','ocrLayout','ocrUseSelection','ocrEnhance'];
function captureProjectControls(){return Object.fromEntries(EXPORT_FIELDS.map(id=>{const el=$(id);return[id,el.type==='checkbox'?el.checked:el.value]}))}
function restoreProjectControls(saved){if(!saved||typeof saved!=='object')return;for(const id of EXPORT_FIELDS){const el=$(id),value=saved[id];if(value===undefined||!el)continue;if(el.type==='checkbox'){if(typeof value==='boolean')el.checked=value;continue}if(typeof value!=='string')continue;if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===value))continue;if(['number','range'].includes(el.type)){const n=Number(value);if(!Number.isFinite(n)||(el.min!==''&&n<Number(el.min))||(el.max!==''&&n>Number(el.max)))continue}el.value=value.slice(0,id==='filename'?80:1000)}for(const id of ['quality','batchQuality'])if($(id+'Out'))$(id+'Out').textContent=$(id).value+'%'}
function checkpointDB(){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(Error('STORAGE_UNAVAILABLE'));const req=indexedDB.open('photo-story-checkpoints-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('STORAGE_BLOCKED'))})}
