async function decodeCheckpoint(record){if(record?.version!==1||!Array.isArray(record.images))throw Error('STORAGE_INVALID');const images=[];try{for(const blob of record.images){if(!(blob instanceof Blob))throw Error('STORAGE_INVALID');const url=URL.createObjectURL(blob);try{const image=await imageFromURL(url),canvas=upscaleCanvas(image.width,image.height);canvas.getContext('2d').drawImage(image,0,0);images.push(canvas)}finally{URL.revokeObjectURL(url)}}function decode(v){if(v===null||typeof v!=='object')return v;if(Object.hasOwn(v,'__photoStoryImage')){if(!Number.isInteger(v.__photoStoryImage)||!images[v.__photoStoryImage])throw Error('STORAGE_INVALID');return images[v.__photoStoryImage]}if(Array.isArray(v))return v.map(decode);return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,decode(x)]))}return decode(record.data)}catch(e){for(const c of images)c.width=c.height=1;throw e}}
let checkpointDirty=false,checkpointSaving=false,checkpointRevision=0,checkpointTimer=0,checkpointKey=null;
