function markCheckpoint(){if(!checkpointReady)return;checkpointDirty=true;checkpointRevision++;checkpointStatus('Alterações ainda não salvas neste navegador.');clearTimeout(checkpointTimer);checkpointTimer=setTimeout(saveCheckpoint,600)}
